﻿using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
public class 大boss代码 : MonoBehaviour {
    private Vector3 pos;
    public GameObject tank;
    public GameObject zidan;
    private GameObject gwt;
    private Vector3 hatPosition;
    private Vector3 por12;
    private int system = 2;
    public int A = 100;
    private GameObject ljn;
    public GameObject zidan2;
    // Use this for initialization
    void Start () {
        pos = this.transform.position;
        StartCoroutine(WaitAndPrint(0.15F));
        StartCoroutine(b(10.0F));
    }

	// Update is called once per frame
	void Update () {
        if (A <= 0)
        {
            Destroy(this.gameObject);
            SceneManager.LoadScene(3);
        }

        if (pos.x < 15 && system % 2 == 0)
        {
            pos = this.transform.position;
            hatPosition = new Vector3((float)(pos.x + 0.3), (float)(pos.y), 0);
            GetComponent<Rigidbody2D>().MovePosition(hatPosition);
        }
        if (pos.x > -16 && system % 2 == 1)
        {
            pos = this.transform.position;
            hatPosition = new Vector3((float)(pos.x - 0.3), (float)(pos.y), 0);
            GetComponent<Rigidbody2D>().MovePosition(hatPosition);
        }
        if (pos.x > 15 && system % 2 == 0)
            system = system + 1;
        if (pos.x < -16 && system % 2 == 1)
            system = system + 1;
    }
    IEnumerator WaitAndPrint(float waitTime)
    {
        for (int i = 0; i <= 999; ++i)
        {
            yield return new WaitForSeconds(waitTime);
            por12 = tank.transform.position;
            Vector3 spawn = new Vector3((float)(por12.x), (float)(por12.y - 3.5), 0);
            gwt = (GameObject)Instantiate(zidan, spawn, Quaternion.identity);
            Destroy(gwt, 6);
        }
    }
    IEnumerator b(float waitTime)
    {
        for (int i = 0; i <= 999; ++i)
        {
            yield return new WaitForSeconds(waitTime);

            Vector3 spawn = new Vector3((float)(5.15619), (float)(55.67343), 0);
            ljn = (GameObject)Instantiate(zidan2, spawn, Quaternion.identity);
            Destroy(ljn, 10);
        }
    }
    void OnCollisionEnter2D(Collision2D coll)
    {
        --A;
        Destroy(coll.gameObject);
    }
}

