﻿using UnityEngine;
using System.Collections;
public class 敌人子弹代码 : MonoBehaviour
{
    //摄像机于要跟随物体的距离
    private Vector3 Dir;
    private Vector3 Dir1;
    private Vector3 Dir2;
    private Vector3 Dir3;
    private Vector3 Dir4;
    public int system = 0;
    //要跟随的物体
    public float speed = 4;
    public GameObject m_Player;
    public GameObject m_Player1;
    public GameObject m_Player2;
    public GameObject m_Player3;
    private Transform transform3;
    // Use this for initialization
    void Start()
    {
        //获取到摄像机于要跟随物体之间的距离
        Dir = m_Player.transform.position - transform.position;
        Dir1 = m_Player.transform.position;
        Dir2 = m_Player1.transform.position;
        Dir3 = m_Player2.transform.position;
        Dir4 = m_Player3.transform.position;
        transform3 = this.GetComponent<Transform>();
    }

    // Update is called once per frame
    void LateUpdate()
    { //摄像机的位置
        if (Input.GetKey(KeyCode.UpArrow) && system == 0)
        {
            float h = Input.GetAxis("Horizontal");
            float v = Input.GetAxis("Vertical");
            transform3.Translate(new Vector3(h, v, 0) * speed * Time.deltaTime);
        }
        else if (Input.GetKey(KeyCode.UpArrow) && system == 1)
        {
            transform.position = m_Player.transform.position - Dir;
            system = 0;
        }
        else if (Input.GetKey(KeyCode.UpArrow) && system == 2)
        {
            transform.position = m_Player.transform.position - Dir;
            system = 0;
        }
        else if (Input.GetKey(KeyCode.UpArrow) && system == 3)
        {
