﻿using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class 敌人射击代码 : MonoBehaviour {
    public GameObject tank;
    public GameObject tank1;
    public GameObject tank2;
    public GameObject tank3;
    public GameObject zidan;
    public GameObject zidan1;
    public GameObject zidan2;
    public GameObject zidan3;
    private GameObject gwt;
    private GameObject ljn;
    private GameObject qdp;
    private GameObject jq;
    private Vector3 por12;
    private Vector3 por13;
    private Vector3 por14;
    private Vector3 por15;
    private Vector3 por;

    // Use this for initialization
    void Start () {
        por12 = tank.transform.position;
        por13 = tank1.transform.position;
        por14 = tank2.transform.position;
        por15 = tank3.transform.position;
    }
    IEnumerator WaitAndPrint(float waitTime)
    {

        for (int i = 0; i <= 8; ++i)
        {

            if (por12.x < 20)
            {
                por = tank.transform.position;
                Vector3 spawn = new Vector3(por.x, (float)(por.y + 1.53), 0);
                gwt = (GameObject)Instantiate(zidan, spawn, Quaternion.identity);
                Destroy(gwt, 6);
            }
            if (por13.x < 20)
            {
                por = tank1.transform.position;
                Vector3 spawn = new Vector3((float)(por.x + 1.6), (float)(por.y), 0);
                ljn = (GameObject)Instantiate(zidan1, spawn, Quaternion.identity);
                Destroy(ljn, 6);
            }
            if (por14.x < 20)
            {
                por = tank2.transform.position;
                Vector3 spawn = new Vector3((float)(por.x - 1.6), (float)(por.y), 0);
                qdp = (GameObject)Instantiate(zidan2, spawn, Quaternion.identity);
                Destroy(qdp, 6);
            }
            if (por15.x < 20)
            {
                por = tank3.transform.position;
                Vector3 spawn = new Vector3(por.x, (float)(por.y - 1.53), 0);
                jq = (GameObject)Instantiate(zidan3, spawn, Quaternion.identity);
                Destroy(jq, 6);
            }
            yield return new WaitForSeconds(waitTime);
        }
    }
    // Update is called once per frame
    void Update () {

        StartCoroutine(WaitAndPrint(5.0F));
    }
}

